import os
from google.cloud import documentai_v1 as documentai

def extract_layout(payload, config=None):
    config = config or {}
    project_id = config.get("project_id") or os.environ["GOOGLE_CLOUD_PROJECT"]
    location = config.get("location", os.environ.get("DOCUMENTAI_LOCATION", "us"))
    processor_id = config.get("processor_id") or os.environ["DOCUMENTAI_PROCESSOR_ID"]
    mime_type = config.get("mime_type", "application/pdf")
    client_options = {"api_endpoint": f"{location}-documentai.googleapis.com"} if location != "us" else None
    client = documentai.DocumentProcessorServiceClient(client_options=client_options)
    name = client.processor_path(project_id, location, processor_id)
    raw_document = documentai.RawDocument(content=payload, mime_type=mime_type)
    request = documentai.ProcessRequest(name=name, raw_document=raw_document)
    response = client.process_document(request=request)
    doc = response.document
    text = doc.text or ""

    def _span_text(text_anchor):
        parts = []
        for segment in getattr(text_anchor, "text_segments", []) or []:
            start = int(getattr(segment, "start_index", 0) or 0)
            end = int(segment.end_index)
            parts.append(text[start:end])
        return "".join(parts)

    def _layout_to_dict(layout):
        if not layout:
            return None
        out = {
            "text": _span_text(layout.text_anchor) if getattr(layout, "text_anchor", None) else "",
            "confidence": float(getattr(layout, "confidence", 0.0) or 0.0),
        }
        if getattr(layout, "bounding_poly", None):
            out["bounding_poly"] = {
                "vertices": [
                    {"x": int(getattr(v, "x", 0) or 0), "y": int(getattr(v, "y", 0) or 0)}
                    for v in getattr(layout.bounding_poly, "vertices", []) or []
                ],
                "normalized_vertices": [
                    {"x": float(getattr(v, "x", 0.0) or 0.0), "y": float(getattr(v, "y", 0.0) or 0.0)}
                    for v in getattr(layout.bounding_poly, "normalized_vertices", []) or []
                ],
            }
        if getattr(layout, "orientation", None):
            out["orientation"] = str(layout.orientation)
        return out

    result = {
        "text": text,
        "pages": [],
        "blocks": [],
        "lines": [],
        "tables": [],
    }
    for page in getattr(doc, "pages", []) or []:
        page_obj = {
            "page_number": int(getattr(page, "page_number", 0) or 0),
            "dimension": {
                "width": float(getattr(getattr(page, "dimension", None), "width", 0.0) or 0.0),
                "height": float(getattr(getattr(page, "dimension", None), "height", 0.0) or 0.0),
                "unit": getattr(getattr(page, "dimension", None), "unit", ""),
            },
            "blocks": [],
            "lines": [],
            "tables": [],
        }

        for block in getattr(page, "blocks", []) or []:
            item = _layout_to_dict(getattr(block, "layout", None))
            page_obj["blocks"].append(item)
            result["blocks"].append(item)

        for line in getattr(page, "lines", []) or []:
            item = _layout_to_dict(getattr(line, "layout", None))
            page_obj["lines"].append(item)
            result["lines"].append(item)

        for table in getattr(page, "tables", []) or []:
            table_item = {
                "layout": _layout_to_dict(getattr(table, "layout", None)),
                "header_rows": [],
                "body_rows": [],
            }
            for row in getattr(table, "header_rows", []) or []:
                row_cells = []
                for cell in getattr(row, "cells", []) or []:
                    row_cells.append(_layout_to_dict(getattr(cell, "layout", None)))
                table_item["header_rows"].append(row_cells)
            for row in getattr(table, "body_rows", []) or []:
                row_cells = []
                for cell in getattr(row, "cells", []) or []:
                    row_cells.append(_layout_to_dict(getattr(cell, "layout", None)))
                table_item["body_rows"].append(row_cells)
            page_obj["tables"].append(table_item)
            result["tables"].append(table_item)

        result["pages"].append(page_obj)
    return result
